                            headers = headersOf("Location", "http://other.example.com/dest"),
                        )
                    } else {
                        hopHeaders = req.headers
                        respond("ok", HttpStatusCode.OK, headersOf("Content-Type", "text/plain"))
                    }
                }
            val transport = TransportOptions.builder().followRedirects(true).build()
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false }, transport)
            runBlocking {
                apiClient.sendRequest(
                    "GET",
                    "http://first.example.com/start",
                    mapOf("Authorization" to "Bearer secret", "X-Trace" to "keep"),
                    null,
                )
            }
            assertNull(
                hopHeaders?.get("Authorization"),
                "Authorization must be stripped on cross-origin redirect",
            )
            assertEquals(
                "keep",
                hopHeaders?.get("X-Trace"),
                "non-sensitive headers must be preserved across the redirect",
            )
        }

        @Test
        @DisplayName("Gap 3.2: noRedirect=false follows redirects normally")
        fun noRedirectFalseFollowsRedirects() {
