        @Test
        @DisplayName("Gap 3.3: HTTPS->HTTPS body replay allowed (no downgrade)")
        fun httpsToHttpsBodyReplayAllowed() {
            // Both legs are HTTPS, so a 307 with a body replays the body and
            // completes — the downgrade guard fires only on HTTPS->HTTP.
            var hopCount = 0
            val engine =
                MockEngine { _ ->
                    hopCount++
                    if (hopCount == 1) {
                        respond(
                            content = "",
                            status = HttpStatusCode.TemporaryRedirect,
                            headers = headersOf("Location", "https://secure.example.com/dest"),
                        )
                    } else {
                        respond("ok", HttpStatusCode.OK, headersOf("Content-Type", "text/plain"))
                    }
                }
            val transport = TransportOptions.builder().followRedirects(true).build()
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false }, transport)
            val response =
                runBlocking {
                    apiClient.sendRequest(
                        "POST",
                        "https://secure.example.com/start",
                        emptyMap(),
                        "payload",
                    )
                }
            assertEquals(200, response.statusCode)
            assertEquals(2, hopCount, "HTTPS->HTTPS body replay must be followed")
        }

